    for i in [root -->][?:Item] {
        if jid(i) == id {
            i.done = not i.done;
            return i;
        }
    }
    return None;
}

def:pub delete_item(id: str) -> bool {
    for i in [root -->][?:Item] {
        if jid(i) == id {
            del i;
            return True;
        }
    }
    return False;
}


