```jac
"""Cross-backend OSP equivalence fixture: a walker's typed entry ability
accumulates node state across spawns. Entry-only subset (no visit/edge-ref) so
the native backend participates; richer traversals are added as native OSP
support lands.

Archetypes are declared ONCE at module level: `obj`/`node`/`edge`/`walker`
declarations are shared across every codespace, so the same `Item`/`Acc` are
compiled by each backend that references them. Only the per-backend entry
functions live in their codespace block.
"""

# --- shared archetypes (one declaration, compiled by every backend) ---
node Item { has val: int; }

walker Acc {
    has total: int = 0;
    can grab with Item entry { self.total = self.total + here.val; }
}

# --- py reference (sv runtime) ---
def acc_py() -> dict[str, any] {
    w = Acc();
    w spawn Item(val=10);
    w spawn Item(val=32);
    return {"total": w.total};
}

# --- na (native LLVM) ---
na {
    def acc_na() -> dict[str, any] {
        w = Acc();
        w spawn Item(val=10);
        w spawn Item(val=32);
        return {"total": w.total};
    }
}

# --- cl (ECMAScript, in-process via the kernel) ---
cl {
    def acc_cl() -> dict[str, any] {
        w = Acc();
        w spawn Item(val=10);
        w spawn Item(val=32);
        return {"total": w.total};
    }
}

```

```jac
"""Cross-backend OSP equivalence fixture: typed / filtered edge references.

The graph mixes edge types: `a -Road-> b`, `a -Rail-> c`, `b -Road-> d`. The
walker follows ONLY `Road` edges via the typed edge ref `[->:Road:->]`, so it
reaches `a, b, d` and never crosses the `Rail` edge to `c`. This pins typed
edge filtering against the untyped `[-->]` (which would also reach `c`).

Backend status: edge connect/ref are E5090 on na and unwired on cl, so py-only
today.
"""

node City { has val: int; }
edge Road {}
edge Rail {}

walker Router {
    has seen: list = [];
    can step with City entry {
        self.seen.append(here.val);
        visit [->:Road:->];
    }
}

def edge_typed_py() -> dict[str, any] {
    a = City(val=1); b = City(val=2); c = City(val=3); d = City(val=4);
    a +>: Road() :+> b;
    a +>: Rail() :+> c;
    b +>: Road() :+> d;
    w = Router();
    w spawn a;
    return {"seen": w.seen};
}

cl {
    def edge_typed_cl() -> dict[str, any] {
        a = City(val=1); b = City(val=2); c = City(val=3); d = City(val=4);
        a +>: Road() :+> b;
        a +>: Rail() :+> c;
        b +>: Road() :+> d;
        w = Router();
        w spawn a;
        return {"seen": w.seen};
    }
}

