Pull the per-item match test in this feed filter out into its own predicate so the comprehension reads cleanly:

```jac
def _search_filter(contents: list, query: str) -> list {
    q = query.lower().strip();
    return [c for c in contents if q in c.lower()];
}
```

Here's a first pass extracting a `_matches` predicate:

```jac
def _matches(item: str, query: str) -> bool {
    q = query.lower().strip();
    return q in item.lower();
}

def _search_filter(contents: list, query: str) -> list {
    return [c for c in contents if _matches(c, query)];
}
```

Good point — recomputing per element is wasteful and needless. `_search_filter` normalizes once and `_matches` receives `q`:

```jac
"""_search_filter: per-item match predicate extracted; query normalized once."""

def _matches(item: str, q: str) -> bool {
    return q in item.lower();
}

def _search_filter(contents: list[str], query: str) -> list {
    q = query.lower().strip();
    return [c for c in contents if _matches(c, q)];
}

with entry {
    contents = ["Hello Jac", "Graph DB rocks", "jac is fun", "Python here"];
    for q in ["  JAC ", "graph", "xyz", ""] {
        print(str(_search_filter(contents, q)));
    }
}
```

