def main():
    edges = {
        "start": [("a", 3), ("b", 2)],
        "a": [("c", 4)],
        "b": [("c", 1), ("d", 5)],
        "c": [("d", 2)],
        "d": [],
    }
    nodes = ["start", "a", "b", "c", "d"]
    preds = {n: [] for n in nodes}
    for u in edges:
        for (v, w) in edges[u]:
            preds[v].append((u, w))

    memo = {}

    def eft(n):
        if n in memo:
            return memo[n]
        best = 0
        for (p, w) in preds[n]:
            best = max(best, eft(p) + w)
        memo[n] = best
        return best

    answer = max(eft(n) for n in nodes)
    print(f"critical path length = {answer}")


if __name__ == "__main__":
    main()
